arguments.argument:
draw_sprite(sprite_index, image_index, x, y)

if image_index=0{sk_draw_midd_text(x, y-8, "추출", c_black)}
if image_index=1{sk_draw_midd_text(x, y-8, "추출중", c_red)}

if progress=-1
{
sk_draw_midd_text(150, 75, "추출할 trc를 선택하십시오.", c_black)
}

if progress=0
{
sk_draw_midd_text(150, 75, "정보를 가져오는중...", c_black)
}

if progress>0
{
sk_draw_midd_text(150, 75, "추출중 --- "+global.file_name[progress], c_black)
}
